#!/usr/bin/env python3
import sys, os, csv, json, gzip, io, math
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b.decode('utf-8-sig').replace('\r\n', '\n').replace('\r', '\n')


def lines_of(text):
    return [l for l in text.split('\n') if l.strip() != '']


def local_to_ts(naive, tz, fold=0):
    return int(naive.replace(tzinfo=tz, fold=fold).timestamp())


def std_offset(tz, ts):
    d = datetime.fromtimestamp(ts, tz)
    return d.utcoffset() - (d.dst() or timedelta(0))


def parse_iso(s):
    s = s.strip()
    if s.endswith('Z') or s.endswith('z'):
        s = s[:-1] + '+00:00'
    d = datetime.fromisoformat(s)
    if d.tzinfo is None:
        d = d.replace(tzinfo=UTC)
    return d


def ts_of(d):
    # exact seconds (fractions dropped via floor)
    return math.floor(d.timestamp())


def norm_dir(s):
    s = s.strip().upper()
    return 'IN' if s in ('IN', 'CLOCK_IN', 'K', 'I') else 'OUT'


def parse_abbr(text, tz):
    out = []
    hdr = None
    for line in lines_of(text):
        row = next(csv.reader([line]))
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            hdr = {n: i for i, n in enumerate(row)}
            continue
        if hdr is None:
            continue
        g = lambda n: row[hdr[n]]
        m, d, y = g('Date').split('/')
        t = g('Time').upper()
        ampm = None
        if t.endswith('AM') or t.endswith('PM'):
            ampm = t[-2:]
            t = t[:-2].strip()
        h, mi, s = [int(x) for x in t.split(':')]
        if ampm:
            h = h % 12 + (12 if ampm == 'PM' else 0)
        naive = datetime(int(y), int(m), int(d), h, mi, s)
        z = g('Zone').upper()
        fold = 0 if z.endswith('DT') else 1
        out.append((g('Record'), g('Badge'), norm_dir(g('Punch')), local_to_ts(naive, tz, fold)))
    return out


def parse_epoch(text, tz):
    out = []
    schema = 1
    for line in lines_of(text):
        o = json.loads(line)
        if not isinstance(o, dict):
            continue
        if 'schema' in o and 'id' not in o and 'punch_id' not in o:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            if 'punch_id' not in o:
                continue
            pid, emp, dr, ts = str(o['punch_id']), o['employee'], o['direction'], math.floor(o['epoch_ms'] / 1000)
        else:
            if 'id' not in o:
                continue
            if 'ts_ms' in o:
                ts = math.floor(o['ts_ms'] / 1000)
            else:
                ts = math.floor(o['ts'])
            pid, emp, dr = str(o['id']), o['emp'], o['dir']
        out.append((pid, emp, norm_dir(dr), int(ts)))
    return out


def parse_offset(text, tz):
    out = []
    rows = [next(csv.reader([l], delimiter=';')) for l in lines_of(text)]
    hdr = None
    for row in rows:
        if 'punch_id' in row and 'timestamp' in row:
            hdr = {n: i for i, n in enumerate(row)}
            continue
        if hdr is None:
            continue
        g = lambda n: row[hdr[n]]
        out.append((g('punch_id'), g('employee'), norm_dir(g('event')), ts_of(parse_iso(g('timestamp')))))
    return out


def parse_legacy(text, tz):
    out = []
    cur_off = None
    for line in lines_of(text):
        t = line[0]
        if t == 'H':
            off = line[13:18].strip()
            if off and off[0] in '+-' and len(off) == 5:
                sign = 1 if off[0] == '+' else -1
                cur_off = sign * timedelta(hours=int(off[1:3]), minutes=int(off[3:5]))
            else:
                cur_off = None
        elif t == 'D':
            pid = line[1:9]
            badge = line[9:15].strip()
            dr = line[15]
            dt = line[16:30]
            naive = datetime.strptime(dt, '%Y%m%d%H%M%S')
            if cur_off is None:
                guess = int(naive.replace(tzinfo=UTC).timestamp())
                off = std_offset(tz, guess)
                # standard offset is constant except historical changes; refine
                ts = guess - int(off.total_seconds())
                off2 = std_offset(tz, ts)
                ts = guess - int(off2.total_seconds())
            else:
                ts = int(naive.replace(tzinfo=UTC).timestamp()) - int(cur_off.total_seconds())
            out.append((pid, 'E' + badge, norm_dir(dr), ts))
    return out


def parse_de(text, tz):
    out = []
    hdr = None
    for line in lines_of(text):
        row = line.split('\t')
        if 'Ausweis' in row:
            hdr = {n.strip(): i for i, n in enumerate(row)}
            continue
        if hdr is None:
            continue
        g = lambda n: row[hdr[n]].strip()
        d, m, y = g('Datum').split('.')
        hh, mm = g('Uhrzeit').split(':')[:2]
        naive = datetime(int(y), int(m), int(d), int(hh), int(mm))
        fold = 0 if g('Zeitzone').upper() == 'MESZ' else 1
        out.append((g('Nr'), g('Ausweis'), norm_dir(g('Buchung')), local_to_ts(naive, tz, fold)))
    return out


def parse_localcsv(text, tz):
    out = []
    hdr = None
    for line in lines_of(text):
        row = next(csv.reader([line]))
        if 'employee_id' in row and 'local_time' in row:
            hdr = {n.strip(): i for i, n in enumerate(row)}
            continue
        if hdr is None:
            continue
        g = lambda n: row[hdr[n]].strip()
        naive = datetime.strptime(g('local_time'), '%Y-%m-%d %H:%M:%S')
        out.append((g('punch_ref'), g('employee_id'), norm_dir(g('direction')), local_to_ts(naive, tz, 0)))
    return out


def parse_localjsonl(text, tz):
    out = []
    for line in lines_of(text):
        o = json.loads(line)
        p = o.get('punch') if isinstance(o, dict) else None
        if not isinstance(p, dict):
            continue
        pid = p['id']
        pid = str(int(pid)) if not isinstance(pid, str) else str(int(pid)) if pid.strip().isdigit() else pid
        naive = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        out.append((pid, p['badge'], norm_dir(p['type']), local_to_ts(naive, tz, 0)))
    return out


PARSERS = {'abbr-csv': parse_abbr, 'epoch-jsonl': parse_epoch, 'offset-csv': parse_offset,
           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_localcsv,
           'local-jsonl': parse_localjsonl}


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = parse_iso(period['corrections_cutoff'])

    def csvrows(name):
        with open(os.path.join(inp, name), encoding='utf-8-sig', newline='') as f:
            return [{k.strip(): (v or '').strip() for k, v in r.items()} for r in csv.DictReader(f)]

    sites = {r['site']: r for r in csvrows('sites.csv')}
    tzs = {s: ZoneInfo(r['timezone']) for s, r in sites.items()}
    employees = csvrows('employees.csv')
    emp_home = {r['employee_id']: r['home_site'] for r in employees}
    rates = {}
    for r in csvrows('rates.csv'):
        rates.setdefault(r['employee_id'], []).append(
            (date.fromisoformat(r['effective_from']), Fraction(Decimal(r['hourly_rate']))))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1 collect
    punches = {}  # (site,id) -> [emp, dir, ts]
    ever = set()
    for site in sorted(sites):
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        parser = PARSERS[sites[site]['format']]
        files = []
        for root, _, fs in os.walk(d):
            for fn in fs:
                files.append(os.path.join(root, fn))
        for path in sorted(files):
            for pid, emp, dr, ts in parser(read_text(path), tzs[site]):
                k = (site, pid)
                ever.add(k)
                if k not in punches:
                    punches[k] = [emp, dr, ts]

    # 2 corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for root, _, fs in os.walk(cdir):
            for fn in fs:
                with open(os.path.join(root, fn), encoding='utf-8-sig', newline='') as f:
                    for r in csv.DictReader(f):
                        r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
                        if r.get('correction_id'):
                            corr.append(r)
    corr = [(parse_iso(r['issued_at']), r) for r in corr]
    corr = [c for c in corr if c[0] <= cutoff]
    corr.sort(key=lambda c: (c[0], c[1]['correction_id']))
    applied = 0
    for _, r in corr:
        k = (r['site'], r['punch_id'])
        a = r['action'].lower()
        if a == 'void':
            if k in punches:
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = ts_of(parse_iso(r['time']))
                applied += 1
        elif a == 'add':
            if k not in ever and r['site'] in sites:
                ever.add(k)
                punches[k] = [r['employee'], norm_dir(r['type']), ts_of(parse_iso(r['time']))]
                applied += 1
    # discard unknown badges
    byemp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in emp_home:
            byemp.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    # helpers
    def rounded(ts, site):
        off = int(datetime.fromtimestamp(ts, tzs[site]).utcoffset().total_seconds())
        loc = ts + off
        r = ((loc + 180) // 360) * 360
        return r - off

    def workday(rts, emp):
        return datetime.fromtimestamp(rts, tzs[emp_home[emp]]).date()

    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0)) for e in emp_home}
    inper = lambda d: pstart <= d <= pend

    for emp, lst in byemp.items():
        lst.sort(key=lambda x: x[:4])
        kept = []
        last = None
        for ts, _, site, pid, dr in lst:
            if last is not None and last[4] == dr and ts - last[0] <= 300:
                if inper(workday(rounded(ts, site), emp)):
                    exc['duplicates_dropped'] += 1
                continue
            last = (ts, 0, site, pid, dr)
            kept.append(last)
        shifts = []
        pend_in = None
        for p in kept:
            rt = rounded(p[0], p[2])
            if p[4] == 'IN':
                if pend_in is not None:
                    if inper(workday(pend_in[1], emp)):
                        exc['open_shifts'] += 1
                pend_in = (p, rt)
            else:
                if pend_in is not None and rt - pend_in[1] <= 16 * 3600:
                    shifts.append((pend_in[0], pend_in[1], rt))
                    pend_in = None
                else:
                    if pend_in is not None:
                        if inper(workday(pend_in[1], emp)):
                            exc['open_shifts'] += 1
                        pend_in = None
                    if inper(workday(rt, emp)):
                        exc['orphan_outs'] += 1
        if pend_in is not None and inper(workday(pend_in[1], emp)):
            exc['open_shifts'] += 1

        rows = []
        for p, rin, rout in shifts:
            wd = workday(rin, emp)
            if not inper(wd):
                continue
            worked = max(0, (rout - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            tz = tzs[p[2]]
            night = 0
            for m in range(rin, rout, 60):
                h = datetime.fromtimestamp(m, tz).hour
                if h >= 22 or h < 6:
                    night += 1
            night = min(night, paid)
            rows.append(dict(rin=rin, wd=wd, paid=paid, night=night))
        rows.sort(key=lambda r: r['rin'])
        daily = {}
        for r in rows:
            before = daily.get(r['wd'], 0)
            after = before + r['paid']
            daily[r['wd']] = after
            r['dot'] = max(0, after - max(before, 480))
        weekly = {}
        for r in rows:
            wk = r['wd'] - timedelta(days=r['wd'].weekday())
            nd = r['paid'] - r['dot']
            before = weekly.get(wk, 0)
            after = before + nd
            weekly[wk] = after
            r['wot'] = max(0, after - max(before, 2400))
        for r in rows:
            ot = r['dot'] + r['wot']
            reg = r['paid'] - ot
            rl = [x for x in rates.get(emp, []) if x[0] <= r['wd']]
            rate = rl[-1][1] if rl else (rates[emp][0][1] if emp in rates else Fraction(0))
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * r['night'] / 60
            e = res[emp]
            e['shifts'] += 1
            e['paid_minutes'] += r['paid']
            e['overtime_minutes'] += ot
            e['night_minutes'] += r['night']
            e['gross'] += pay

    def cents(fr):
        c = math.floor(fr * 100 + Fraction(1, 2))
        return c

    out_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totc = 0
    for e in sorted(res):
        v = res[e]
        c = cents(v['gross'])
        totc += c
        for k in tot:
            tot[k] += v[k]
        out_emps[e] = dict(shifts=v['shifts'], paid_minutes=v['paid_minutes'],
                           overtime_minutes=v['overtime_minutes'], night_minutes=v['night_minutes'],
                           gross='%d.%02d' % divmod(c, 100))
    tot['gross'] = '%d.%02d' % divmod(totc, 100)
    with open(outp, 'w') as f:
        json.dump(dict(period=dict(start=period['start'], end=period['end']), employees=out_emps,
                       exceptions=exc, totals=tot), f, indent=1)


main()
